    q=[(r,c) for r in range(h) for c in range(w) if mask[r,c] and not (r in(0,h-1) or c in(0,w-1))]
    # flood from edge through bg cells
    q=[(r,c) for r in range(h) for c in range(w) if (r in(0,h-1) or c in(0,w-1)) and not mask[r,c]]
    seen[:]=np.where((r_:=None),False,False)
    out=np.zeros_like(mask); st=list(q)
    while st:
        r,c=st.pop(); out[r,c]=True
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and not out[nr,nc] and not mask[nr,nc]:
